INSERT INTO repository_locations (id,repository_id,machine_name,root_path,git_dir_path,current_branch,head_sha,is_dirty) VALUES ($1,$2,$3,$4,$5,$6,$7,COALESCE($8,false)) ON CONFLICT (machine_name,root_path) DO UPDATE SET repository_id=EXCLUDED.repository_id,git_dir_path=EXCLUDED.git_dir_path,current_branch=COALESCE($6,repository_locations.current_branch),head_sha=COALESCE($7,repository_locations.head_sha),is_dirty=COALESCE($8,repository_locations.is_dirty),last_seen_at=now(),is_present=true RETURNING id
